import{_ as e,o as n,c as a,S as l}from"./chunks/framework.D1Ss-Xl7.js";const m=JSON.parse('{"title":"Vue表单组件如何自动化输入","description":"","frontmatter":{"title":"Vue表单组件如何自动化输入","date":"2020-04-23 22:43","comments":true,"archives":2020,"tags":["frontend","vue"]},"headers":[],"relativePath":"posts/2020-04-23-vue-hack-form/index.md","filePath":"posts/2020/2020-04-23-vue-hack-form.md"}'),p={name:"posts/2020-04-23-vue-hack-form/index.md"};function o(t,s,r,c,i,u){return n(),a("div",null,[...s[0]||(s[0]=[l(`<p>使用 Vue 的数据双向绑定功能可以很方便的完成表单的数据收集和提交，再也不用自己手动监听事件和收集数据了。但同时自动化输入也变得复杂起来。</p><h2 id="传统表单自动化输入" tabindex="-1">传统表单自动化输入 <a class="header-anchor" href="#传统表单自动化输入" aria-label="Permalink to &quot;传统表单自动化输入&quot;">​</a></h2><p>对于传统的表单我们可以很简单的自动化输入过程，例如<code>checkbox</code>和<code>input</code>元素，我们可以自动选中和输入内容：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">document.</span><span style="color:#6F42C1;">querySelector</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;.checkbox&#39;</span><span style="color:#24292E;">).checked </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> true</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">document.</span><span style="color:#6F42C1;">querySelector</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;.input&#39;</span><span style="color:#24292E;">).value </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> true</span><span style="color:#24292E;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>当用户提交的时候，程序会读取相应元素的值，然后填充到请求里。</p><h2 id="vue-组件自动化输入" tabindex="-1">Vue 组件自动化输入 <a class="header-anchor" href="#vue-组件自动化输入" aria-label="Permalink to &quot;Vue 组件自动化输入&quot;">​</a></h2><p>这里我们以现在流行的<a href="https://element.eleme.io/#/en-US" target="_blank" rel="noreferrer">Element</a>为例子演示如何自动化输入。用过 Vue 的人都知道， <code>v-model</code>是用来进行双向绑定的。它的原理是：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Vue.</span><span style="color:#6F42C1;">component</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;custom-input&#39;</span><span style="color:#24292E;">, {</span></span>
<span class="line"><span style="color:#24292E;">  props: [</span><span style="color:#032F62;">&#39;value&#39;</span><span style="color:#24292E;">],</span></span>
<span class="line"><span style="color:#24292E;">  template: </span><span style="color:#032F62;">\`</span></span>
<span class="line"><span style="color:#032F62;">    &lt;input</span></span>
<span class="line"><span style="color:#032F62;">      v-bind:value=&quot;value&quot;</span></span>
<span class="line"><span style="color:#032F62;">      v-on:input=&quot;$emit(&#39;input&#39;, $event.target.value)&quot;</span></span>
<span class="line"><span style="color:#032F62;">    &gt;</span></span>
<span class="line"><span style="color:#032F62;">  \`</span></span>
<span class="line"><span style="color:#24292E;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>到这里，我们就知道了通过<code>$emit(&#39;input&#39;, value)</code>的方式，可以绑定想要输入的值，直接使用传统方式修改<code>input</code>元素的值，有时候不会触发<code>input</code>事件，所以不是一个可行的办法。</p><p>接下来，我们讲下如何选中元素并调用<code>$emit</code>，例子是 Vue 官网的<a href="https://element.eleme.io/#/en-US/component/input" target="_blank" rel="noreferrer">搜索框</a></p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> input</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> document.</span><span style="color:#6F42C1;">querySelector</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;.el-input&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">input.__vue__.</span><span style="color:#6F42C1;">$emit</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;input&#39;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;Hello world&#39;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>在<code>console</code>里输入这两行代码，你会发现搜索框里被填入了<code>Hello World</code>。Vue 实例被隐藏到了 DOM 中，只要知道如何访问 Vue 然好调用<code>$emit</code>，问题就迎刃而解。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>现在的前端框架用起来方便，但也隐藏了大量细节。导致做自动化的时候不知道如何下手，尝试修改元素的值，但发现提交的时候还是没有带上正确的数值。这时候就需要思考框架绑定数据的本质是什么， 弄清了本质，其实做起来发现更简单！</p>`,14)])])}const y=e(p,[["render",o]]);export{m as __pageData,y as default};
